const base32Alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
const base32Encode=buffer=>{let bits="",out="";for(const byte of buffer)bits+=byte.toString(2).padStart(8,"0");for(let i=0;i<bits.length;i+=5)out+=base32Alphabet[parseInt(bits.slice(i,i+5).padEnd(5,"0"),2)];return out};
const base32Decode=value=>{let bits="";for(const char of String(value).replace(/=|\s/g,"").toUpperCase()){const index=base32Alphabet.indexOf(char);if(index<0)continue;bits+=index.toString(2).padStart(5,"0")}const bytes=[];for(let i=0;i+8<=bits.length;i+=8)bytes.push(parseInt(bits.slice(i,i+8),2));return Buffer.from(bytes)};
const totp=(secret,time=Date.now())=>{const counter=Math.floor(time/30000),buffer=Buffer.alloc(8);buffer.writeBigUInt64BE(BigInt(counter));const digest=crypto.createHmac("sha1",base32Decode(secret)).update(buffer).digest(),offset=digest[digest.length-1]&15,code=(digest.readUInt32BE(offset)&0x7fffffff)%1000000;return String(code).padStart(6,"0")};
const validTotp=(secret,code)=>[-1,0,1].some(step=>totp(secret,Date.now()+step*30000)===String(code||"").trim());
const strongPassword=value=>typeof value==="string"&&value.length>=10&&/[a-z]/.test(value)&&/[A-Z]/.test(value)&&/\d/.test(value)&&/[^A-Za-z0-9]/.test(value);

