function audit(req, action, entity, detail) {
  db.audit.unshift({ id: id("AU"), action, user: req.user?.name || "System", entity, detail, createdAt: now() });
  db.audit = db.audit.slice(0, 5000);
}
function auth(req, res, next) {
  const token = (req.headers.authorization || "").replace("Bearer ", "");
  const session = sessions.get(token),userId=typeof session==="string"?session:session?.userId;
  const user = db.users.find(x => x.id === userId && x.active&&!x.archived);
  if (!user) return res.status(401).json({ error: "Please sign in." });
  if(typeof session==="object")session.lastSeen=now();
  const path=req.path,module=path.startsWith("/api/sales")?"sales":path.startsWith("/api/bookings")?"bookings":path.startsWith("/api/customers")?"customers":path.startsWith("/api/quotes")?"quotes":path.startsWith("/api/wallet")||path.startsWith("/api/ledger")||path.startsWith("/api/finance")?"finance":path.startsWith("/api/passports")?"passports":path.startsWith("/api/refunds")?"refunds":path.startsWith("/api/cases")?"cases":path.startsWith("/api/reports")?"reports":path.startsWith("/api/users")||path.startsWith("/api/roles")?"users":path.startsWith("/api/audit")?"audit":null;
  if(module&&!user.permissions?.[module]&&!admin({user}))return res.status(403).json({error:`You do not have permission to access ${module}.`});
  req.user = user;req.sessionToken=token;next();
}
const admin=req=>["Agency owner","Agency administrator"].includes(req.user.role);
const approvalAllowed=(req,type,amount)=>req.user.role==="Agency owner"||Number(req.user.approvalLimits?.[type]||0)>=Math.abs(Number(amount||0));
const safeUser=user=>{const {passwordHash,twoFactorSecret,twoFactorPendingSecret,profilePhotoData,documents,...safe}=user;return{...safe,hasProfilePhoto:Boolean(profilePhotoData),documents:(documents||[]).map(({data,...document})=>document)}};
const periodLocked=date=>db.finance.lockedPeriods.some(p=>p.status==="Locked"&&date>=p.from&&date<=p.to);
const baseAmount=(amount,currency,rate)=>Number(amount)*Number(currency===db.finance.settings.baseCurrency?1:rate||db.finance.settings.exchangeRates[currency]||1);
function financeSummary(from="0000-01-01",to="9999-12-31"){
  const movements=[...db.walletTransactions].sort((a,b)=>a.date.localeCompare(b.date));
  const baseline=Number(db.wallet.balance)-movements.reduce((s,x)=>s+baseAmount(x.amount,x.currency,x.exchangeRate),0);
  const opening=baseline+movements.filter(x=>x.date<from).reduce((s,x)=>s+baseAmount(x.amount,x.currency,x.exchangeRate),0);
  let running=opening;
  const walletRows=movements.filter(x=>x.date>=from&&x.date<=to).map(x=>({...x,baseAmount:baseAmount(x.amount,x.currency,x.exchangeRate),runningBalance:(running+=baseAmount(x.amount,x.currency,x.exchangeRate))}));
  const ledgerRows=db.ledger.filter(x=>x.date>=from&&x.date<=to);
  const receivables=db.bookings.map(b=>({...b,paidAmount:Number(b.paidAmount??(b.paymentStatus==="Paid"?b.total:0)),outstanding:Math.max(0,Number(b.total)-Number(b.paidAmount??(b.paymentStatus==="Paid"?b.total:0)))})).filter(b=>b.outstanding>0);
  const payables=db.bookings.filter(b=>b.status==="Ticketed").map(b=>({...b,outstandingPayable:Math.max(0,Number(b.cost||0)-Number(b.supplierPaid||0))})).filter(b=>b.outstandingPayable>0);
  return {openingBalance:opening,closingBalance:running,walletRows,ledgerRows,receivables,payables};
}
