app.post("/api/login", (req, res) => {
  const user = db.users.find(x => x.email.toLowerCase() === String(req.body.email || "").toLowerCase() && x.passwordHash === hash(String(req.body.password || "")) && x.active&&!x.archived);
  if (!user) return res.status(401).json({ error: "Email or password is incorrect." });
  if(user.twoFactorEnabled&&!validTotp(user.twoFactorSecret,req.body.otp))return res.status(401).json({error:"A valid 6-digit authenticator code is required.",requiresTwoFactor:true});
  const token = crypto.randomBytes(24).toString("hex"); sessions.set(token,{userId:user.id,createdAt:now(),lastSeen:now(),ip:req.ip,userAgent:req.headers["user-agent"]||"Unknown"});user.lastLoginAt=now();user.lastLoginIp=req.ip;
  audit({ user }, "SIGNED_IN", "User", user.email); save();
  res.json({ token, user: { id: user.id, name: user.name, email: user.email, role: user.role, branch: user.branch,mustChangePassword:user.mustChangePassword,twoFactorEnabled:user.twoFactorEnabled } });
});
