app.post("/api/grocery/purchases/:purchaseId/receive",auth,(req,res)=>{const p=db.grocery.purchases.find(x=>x.id===req.params.purchaseId);if(!p)return res.status(404).json({error:"Purchase not found."});if(["Draft","Pending approval","Rejected","Cancelled"].includes(p.status))return res.status(409).json({error:"Approve or order this purchase before receiving goods."});const receipts=Array.isArray(req.body.items)?req.body.items:[];for(const received of receipts){const item=p.items.find(x=>x.id===received.itemId),quantity=Number(received.quantity||0),rejected=Number(received.rejected||0);if(!item||quantity<0||rejected<0||item.receivedQty+item.rejectedQty+quantity+rejected>item.orderedQty+.001)return res.status(400).json({error:"Received and rejected quantities cannot exceed the ordered quantity."});item.receivedQty+=quantity;item.rejectedQty+=rejected;if(received.batchNumber)item.batchNumber=received.batchNumber;if(received.expiry)item.expiry=received.expiry;const product=db.grocery.products.find(x=>x.id===item.productId);if(product&&quantity>0){product.stock=Number(product.stock||0)+quantity;product.cost=item.unitCost;if(item.batchNumber)product.batchNumber=item.batchNumber;if(item.expiry){product.expiry=item.expiry;product.trackExpiry=true}}}const receivedTotal=p.items.reduce((s,x)=>s+x.receivedQty,0),orderedTotal=p.items.reduce((s,x)=>s+x.orderedQty,0);p.receivingStatus=receivedTotal<=0?"Not received":receivedTotal<orderedTotal?"Partially received":"Received";p.status=p.receivingStatus==="Received"?"Received":p.status;p.receivedBy=req.user.name;p.receivedAt=now();const supplier=db.grocery.suppliers.find(x=>x.id===p.supplierId);if(supplier&&!p.payablePosted){supplier.balance=Number(supplier.balance||0)+p.total;p.payablePosted=true}p.history.push({action:p.receivingStatus,user:req.user.name,at:now()});db.grocery.audit.unshift({id:id("GA"),action:"PURCHASE_RECEIVED",detail:`${p.poNumber} • ${p.receivingStatus}`,createdAt:now()});save();res.json(p)});
app.post("/api/grocery/purchases/:purchaseId/pay",auth,(req,res)=>{const p=db.grocery.purchases.find(x=>x.id===req.params.purchaseId);if(!p)return res.status(404).json({error:"Purchase not found."});const payments=Array.isArray(req.body.payments)?req.body.payments:[],allowed=["Cash","eSewa","Khalti","Bank"],clean=[];for(const raw of payments){const method=String(raw.method||""),amount=Number(raw.amount||0);if(!allowed.includes(method)||!Number.isFinite(amount)||amount<0)return res.status(400).json({error:"Enter valid payment amounts."});if(!amount)continue;if(method==="Bank"&&!String(raw.bankName||"").trim())return res.status(400).json({error:"Bank name is required."});clean.push({id:id("PPAY"),date:req.body.date||now().slice(0,10),method,amount,bankName:method==="Bank"?raw.bankName:"",bankDetails:method==="Bank"?raw.bankDetails||"":"",createdBy:req.user.name,createdAt:now()})}const amount=clean.reduce((s,x)=>s+x.amount,0);if(amount<=0||amount>p.outstanding+.009)return res.status(400).json({error:"Payment must be greater than zero and cannot exceed the outstanding balance."});p.payments.push(...clean);p.paidAmount+=amount;p.outstanding=Math.max(0,p.total-p.paidAmount);p.paymentStatus=p.outstanding<.01?"Paid":"Partially paid";const supplier=db.grocery.suppliers.find(x=>x.id===p.supplierId);if(supplier)supplier.balance=Math.max(0,Number(supplier.balance||0)-amount);p.history.push({action:`Payment ${amount.toFixed(2)}`,user:req.user.name,at:now()});db.grocery.audit.unshift({id:id("GA"),action:"PURCHASE_PAYMENT",detail:`${p.poNumber} • ${amount.toFixed(2)}`,createdAt:now()});save();res.json(p)});
app.post("/api/grocery/purchases/:purchaseId/return",auth,(req,res)=>{const p=db.grocery.purchases.find(x=>x.id===req.params.purchaseId);if(!p)return res.status(404).json({error:"Purchase not found."});const item=p.items.find(x=>x.id===req.body.itemId),quantity=Number(req.body.quantity||0);if(!item||quantity<=0||item.returnedQty+quantity>item.receivedQty)return res.status(400).json({error:"Return quantity cannot exceed received quantity."});item.returnedQty+=quantity;const product=db.grocery.products.find(x=>x.id===item.productId);if(!product||product.stock<quantity)return res.status(409).json({error:"Current stock is insufficient for this return."});product.stock-=quantity;const value=quantity*item.unitCost,supplier=db.grocery.suppliers.find(x=>x.id===p.supplierId);if(supplier)supplier.balance=Math.max(0,Number(supplier.balance||0)-value);p.history.push({action:`Returned ${quantity} ${item.unit} of ${item.productName}: ${req.body.reason||"Supplier return"}`,user:req.user.name,at:now()});db.grocery.audit.unshift({id:id("GA"),action:"PURCHASE_RETURN",detail:`${p.poNumber} • ${item.productName} • ${quantity}`,createdAt:now()});save();res.json(p)});

const airports = { KTM:"Kathmandu", DXB:"Dubai", DEL:"Delhi", DOH:"Doha", SIN:"Singapore", BKK:"Bangkok", LHR:"London", JFK:"New York", HKG:"Hong Kong", SYD:"Sydney", NRT:"Tokyo", CDG:"Paris" };
const carriers = [
  ["QR","Qatar Airways","DOH"],["EK","Emirates","DXB"],["AI","Air India","DEL"],["SQ","Singapore Airlines","SIN"],["TG","Thai Airways","BKK"],["CX","Cathay Pacific","HKG"]
];
function offers(q) {
  const origin = String(q.origin || "KTM").toUpperCase(), destination = String(q.destination || "DXB").toUpperCase();
  const cabinFactor = q.cabin === "Business" ? 2.8 : q.cabin === "First" ? 5.2 : q.cabin === "Premium economy" ? 1.45 : 1;
  const pax = Math.max(1, Number(q.adults || 1) + Number(q.children || 0));
  const baseSeed = [...origin+destination].reduce((s,c)=>s+c.charCodeAt(0),0);
  return carriers.slice(0,5).map((c,i) => {
    const base = Math.round((145 + (baseSeed % 180) + i * 37) * cabinFactor * pax);
    const taxes = Math.round(base*.22), supplierFee = 6+i, supplierCost = base+taxes+supplierFee, total=supplierCost;
    const stop = c[2] === origin || c[2] === destination || i === 2 ? 0 : 1;
    return { id:`OFF-${Date.now()}-${i}`, airline:c[1], carrier:c[0], flight:`${c[0]} ${210+i*37}`, origin, destination, originName:airports[origin]||origin, destinationName:airports[destination]||destination,
      departure:q.departure, departTime:`${String(7+i*2).padStart(2,"0")}:${i%2?"35":"10"}`, arriveTime:`${String(11+i*2).padStart(2,"0")}:${i%2?"20":"55"}`,
      duration:`${4+i}h ${15+i*7}m`, stops:stop, cabin:q.cabin||"Economy", brand:i%2?"Flex":"Value", baggage:i%2?"30 kg":"25 kg", refundable:i%2===1,
      seats:3+i, base, taxes, supplierFee, supplierCost, total, currency:q.currency||"USD", source:i%2?"NDC Sandbox":"GDS Sandbox", expiresAt:new Date(Date.now()+15*60000).toISOString() };
  });
}
app.post("/api/search", auth, (req,res) => { const result=offers(req.body); audit(req,"FLIGHT_SEARCH","Search",`${req.body.origin}–${req.body.destination}`); save(); res.json(result); });
app.post("/api/quotes", auth, (req,res) => {
  const customerName=String(req.body.customerName||"").trim(),origin=String(req.body.origin||"").trim().toUpperCase(),destination=String(req.body.destination||"").trim().toUpperCase();
  const fare=Number(req.body.fare||0),serviceFee=Number(req.body.serviceFee||0);
  if(!customerName||!origin||!destination||!req.body.travelDate)return res.status(400).json({error:"Customer, from, to and travel date are required."});
  if(origin===destination)return res.status(400).json({error:"From and to airports must be different."});
  if(!Number.isFinite(fare)||fare<0||!Number.isFinite(serviceFee)||serviceFee<0)return res.status(400).json({error:"Fare and service fee must be valid positive amounts."});
  const quote={
    id:id("QT"),customerName,origin,destination,route:`${origin} → ${destination}`,travelDate:req.body.travelDate,
    airline:String(req.body.airline||"").trim(),flight:String(req.body.flight||"").trim().toUpperCase(),fare,serviceFee,total:fare+serviceFee,
    baggage:String(req.body.baggage||"").trim(),conditions:String(req.body.conditions||"").trim(),notes:String(req.body.notes||"").trim(),
    status:String(req.body.status||"Draft"),validUntil:req.body.validUntil||new Date(Date.now()+24*3600000).toISOString().slice(0,10),branch:req.user.branch,createdBy:req.user.name,createdAt:now()
  };
  db.quotes.unshift(quote); audit(req,"QUOTE_CREATED","Quote",quote.id); save(); res.status(201).json(quote);
});
