app.post("/api/passports",auth,(req,res)=>{
  const customerName=String(req.body.customerName||"").trim(),passportNumber=String(req.body.passportNumber||"").trim().toUpperCase(),applicationReference=String(req.body.applicationReference||"").trim();
  if(!customerName||!passportNumber||!applicationReference||!req.body.applicationDate)return res.status(400).json({error:"Passenger, passport number, application reference and application date are required."});
  if(db.passportServices.some(x=>x.applicationReference.toLowerCase()===applicationReference.toLowerCase()))return res.status(409).json({error:"That passport application reference already exists."});
  const fee=Number(req.body.fee||0);if(!Number.isFinite(fee)||fee<0)return res.status(400).json({error:"Enter a valid service fee."});
  const record={id:id("PSP"),serviceType:req.body.serviceType||"Passport renewal",customerId:req.body.customerId||"",customerName,phone:req.body.phone||"",passportNumber,currentExpiry:req.body.currentExpiry||"",applicationReference,applicationDate:req.body.applicationDate,appointmentDate:req.body.appointmentDate||"",submissionOffice:req.body.submissionOffice||"",expectedReadyDate:req.body.expectedReadyDate||"",status:req.body.status||"Application received",fee,paymentStatus:req.body.paymentStatus||"Pending",paymentMethod:req.body.paymentMethod||"",notes:req.body.notes||"",branch:req.user.branch,createdBy:req.user.name,createdAt:now(),updatedAt:now()};
  db.passportServices.unshift(record);audit(req,"PASSPORT_RENEWAL_CREATED","Passport service",`${record.applicationReference}: ${record.customerName}`);save();res.status(201).json(record);
});
app.patch("/api/passports/:passportId",auth,(req,res)=>{
  const record=db.passportServices.find(x=>x.id===req.params.passportId);if(!record)return res.status(404).json({error:"Passport service record not found."});
  const allowed=["status","appointmentDate","expectedReadyDate","submissionOffice","paymentStatus","paymentMethod","notes","newPassportNumber","newExpiry","collectionDate","collectionMethod","collectorName","collectorRelation","collectorPhone","collectorIdType","collectorId","deliveredBy","documentCondition","collectionNote"];
  for(const key of allowed)if(req.body[key]!==undefined)record[key]=req.body[key];
  if(record.status==="Collected"&&(!record.collectionDate||!record.collectorName))return res.status(400).json({error:"Collection date and collector name are required."});
  record.updatedAt=now();record.updatedBy=req.user.name;audit(req,record.status==="Collected"?"PASSPORT_COLLECTED":"PASSPORT_STATUS_UPDATED","Passport service",`${record.applicationReference}: ${record.status}`);save();res.json(record);
});
app.get("/api/sales",auth,(req,res)=>{let rows=db.sales;if(!admin(req)&&req.user.branch)rows=rows.filter(x=>x.branch===req.user.branch);res.json(rows)});
app.post("/api/sales",auth,(req,res)=>{
  const total=Number(req.body.total),description=String(req.body.description||"").trim(),customerName=String(req.body.customerName||"Walk-in customer").trim(),payments=Array.isArray(req.body.payments)?req.body.payments:[];
  if(!description)return res.status(400).json({error:"Enter what was sold."});
  if(!Number.isFinite(total)||total<=0)return res.status(400).json({error:"Sale total must be greater than zero."});
  const allowedMethods=["Cash","eSewa","Khalti","Bank"],cleanPayments=[];
  for(const payment of payments){const method=String(payment.method||""),amount=Number(payment.amount||0);if(!allowedMethods.includes(method))return res.status(400).json({error:"Use Cash, eSewa, Khalti or Bank."});if(!Number.isFinite(amount)||amount<0)return res.status(400).json({error:"Payment amounts cannot be negative."});if(amount===0)continue;const bankName=String(payment.bankName||"").trim(),bankDetails=String(payment.bankDetails||"").trim();if(method==="Bank"&&!bankName)return res.status(400).json({error:"Bank name is required when a bank amount is entered."});cleanPayments.push({method,amount,bankName:method==="Bank"?bankName:"",bankDetails:method==="Bank"?bankDetails:"",reference:String(payment.reference||"").trim()})}
  const received=cleanPayments.reduce((sum,payment)=>sum+payment.amount,0);if(Math.abs(received-total)>.009)return res.status(400).json({error:`Split payments total ${received.toFixed(2)}, but sale total is ${total.toFixed(2)}.`});
  const sale={id:id("SALE"),date:req.body.date||now().slice(0,10),customerName,description,reference:String(req.body.reference||"").trim(),total,payments:cleanPayments,note:String(req.body.note||"").trim(),branch:req.user.branch,createdBy:req.user.name,createdAt:now()};db.sales.unshift(sale);
  const journalId=id("JR"),common={journalId,date:sale.date,type:"Direct sale",reference:sale.id,category:"Service fees",entityType:"Sale",entityId:sale.id,status:"Posted",currency:db.finance.settings.baseCurrency,exchangeRate:1,createdBy:req.user.name,createdAt:now(),note:sale.note};
  db.ledger.unshift(...cleanPayments.map(payment=>({id:id("LE"),...common,account:payment.method==="Bank"?`Bank: ${payment.bankName}`:payment.method,debit:payment.amount,credit:0,paymentMethod:payment.method,bankName:payment.bankName})),{id:id("LE"),...common,account:"Sales income",debit:0,credit:total});
  audit(req,"SALE_RECORDED","Sale",`${sale.id}: ${total} (${cleanPayments.map(x=>`${x.method} ${x.amount}`).join(", ")})`);save();res.status(201).json(sale);
});
